import { useState, type CSSProperties, type ReactNode } from 'react'
import { Apple, Gift, Nfc, Smartphone, UserPlus } from 'lucide-react'
import type { PassContent } from '@/lib/walletContent'
import { useQrDataUrl } from '@/hooks/useQrDataUrl'
import { Segmented } from '@/components/ui/Tabs'
import { cn } from '@/lib/cn'
import { StampGlyph } from './StampGlyph'

type View = 'ios' | 'android' | 'signup'

function Qr({ code, size = 120 }: { code: string; size?: number }) {
  // The QR is auto-generated by the system and not editable by the business (§4.3).
  const url = useQrDataUrl(code, size)
  return url ? <img src={url} alt="Pass QR code (generated by the system)" /> : <span className="block aspect-square" />
}

/**
 * Wallet card in the client's reference layout: logo tile and brand line, card type and headline,
 * a row of stamp circles with "6 / 10 STAMPS", a reward block and the QR ("Show to redeem").
 * Points, Tier and Membership cards keep the same frame with a balance/tier figure instead of stamps.
 */
export function WalletCard({ content, qrCode = 'BNC-PREVIEW', compact = false, className }: { content: PassContent; qrCode?: string; compact?: boolean; className?: string }) {
  const grid = content.stampGrid
  const columns = grid ? Math.min(grid.total, 10) : 0
  const style = { '--bgp': content.background, '--fg': content.textColor, '--ac': content.accentColor } as CSSProperties
  return (
    <div className={cn('wcard', compact && 'compact', className)} style={style} data-testid="wallet-pass">
      <span className="wc-notch" aria-hidden />
      <div className="wc-head">
        <span className="wc-logo">{content.logo ? <img src={content.logo} alt="" /> : content.brand.slice(0, 1)}</span>
        <span className="wc-brand min-w-0">
          <b>{content.brand}</b>
          {content.subtitle && <small className="truncate">{content.subtitle}</small>}
        </span>
        <span className="wc-type">
          <small>{content.typeLabel}</small>
          {content.headline && <b>{content.headline}</b>}
        </span>
        {!compact && <Nfc className="wc-nfc" aria-hidden />}
      </div>
      {content.heroImage && !compact && <img src={content.heroImage} alt="" className="wc-hero" />}

      {grid ? (
        <>
          <div className="wc-stamps" style={{ gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` }} aria-label={`${grid.filled} of ${grid.total} stamps`}>
            {Array.from({ length: grid.total }, (_, i) => (
              <span key={i} className={cn('wc-stamp', i < grid.filled && 'on')}>
                {i < grid.filled && <StampGlyph icon={grid.icon} className="size-[55%]" />}
              </span>
            ))}
          </div>
          <p className="wc-count">
            {grid.filled} / {grid.total} stamps
          </p>
        </>
      ) : (
        <div className="wc-body">
          {content.big && <p className="wc-big">{content.big}</p>}
          {content.primary && !content.big && <p className="wc-big">{content.primary.value}</p>}
          {content.progress && (
            <div className="wc-bar">
              <i style={{ '--w': `${Math.min(100, (content.progress.value / Math.max(1, content.progress.max)) * 100)}%` } as CSSProperties} />
            </div>
          )}
          {content.progress && <p className="wc-sub">{content.progress.label}</p>}
        </div>
      )}

      <div className="wc-foot">
        <span className="wc-gift" aria-hidden>
          <Gift />
        </span>
        {content.footer && (
          <span className="wc-reward min-w-0">
            <small>{content.footer.label}</small>
            <b className="line-clamp-2">{content.footer.value}</b>
            {content.footer.sub && <span>{content.footer.sub}</span>}
          </span>
        )}
        <span className="wc-qr">
          <Qr code={qrCode} />
          <small>Show to redeem</small>
        </span>
      </div>
      {content.redeemed && <p className="mt-3 inline-block rounded-md bg-white/90 px-2 py-0.5 text-xs font-bold text-black">REDEEMED</p>}
    </div>
  )
}

/**
 * Live wallet mockup: "this is how it will look on iPhone / Android" (spec §4.3) plus, when given,
 * the customer sign-up page view. Approximation only — real rendering is done by Apple / Google Wallet.
 */
export function WalletPassPreview({ content, label = 'Live wallet preview', signup, initialView = 'ios' }: { content: PassContent; label?: string; signup?: ReactNode; initialView?: View }) {
  const [view, setView] = useState<View>(initialView)
  const items: { value: View; label: ReactNode }[] = [
    { value: 'ios', label: <><Apple className="size-[15px]" aria-hidden /> iPhone</> },
    { value: 'android', label: <><Smartphone className="size-[15px]" aria-hidden /> Android</> },
  ]
  if (signup) items.push({ value: 'signup', label: <><UserPlus className="size-[15px]" aria-hidden /> Sign-up page</> })
  const current = view === 'signup' && !signup ? 'ios' : view

  return (
    <section aria-label={label} className="preview-col">
      <Segmented label="Preview" value={current} onChange={setView} items={items} />
      <div className={cn('phone max-w-full', current === 'android' && 'android')}>
        <div className={cn('phone-screen flex flex-col', current === 'signup' && 'signup-screen')}>
          {current === 'signup' ? (
            signup
          ) : (
            <>
              <p className="wc-status">{current === 'ios' ? 'Apple Wallet' : 'Google Wallet'}</p>
              <WalletCard content={content} />
              <p className="mt-auto pt-6 text-center text-[9px] tracking-[0.3em] text-[#9A9AA3] uppercase">Powered by Bonuca</p>
            </>
          )}
        </div>
        <p className="phone-cap">
          {current === 'signup' ? 'Customer sign-up page (shown after the first scan)' : `${content.typeLabel} · ${current === 'ios' ? 'Apple Wallet' : 'Google Wallet'} (approximate)`}
        </p>
      </div>
    </section>
  )
}
